"use client";

const pillars = [
  {
    id: "01",
    title: "Precision",
    description: "Code is not just functionality; it is structure. We architect systems with mathematical exactness, eliminating redundancy and maximizing efficiency."
  },
  {
    id: "02",
    title: "Velocity",
    description: "Speed is a feature. We build infrastructure that allows your team to ship faster, safely. No bottlenecks, just momentum."
  },
  {
    id: "03",
    title: "Resilience",
    description: "Systems must survive success. We architect for scale from day one, ensuring stability under the pressure of millions of users."
  }
];

export default function Focus() {
  return (
    <section id="focus" className="py-32 bg-zinc-950 border-b border-zinc-900 overflow-hidden">
      <div className="container-width">
        <div className="grid lg:grid-cols-3 gap-12 lg:gap-8">
          {pillars.map((pillar) => (
            <div key={pillar.id} className="relative group">
              {/* Large Sculptural Number */}
              <div className="text-[12rem] font-bold text-zinc-900/50 leading-none absolute -top-24 -left-6 select-none pointer-events-none group-hover:text-zinc-800 transition-colors duration-500">
                {pillar.id}
              </div>

              <div className="relative z-10 pt-16 pl-6 border-l border-zinc-800 group-hover:border-zinc-600 transition-colors h-full">
                <h3 className="text-2xl font-bold text-white mb-6">
                  {pillar.title}
                </h3>
                <p className="text-zinc-400 leading-relaxed text-lg font-light">
                  {pillar.description}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
