export default function TechStack() {
  return (
    <section className="py-20 bg-zinc-950 border-b border-zinc-900 overflow-hidden relative group">
      <div className="absolute inset-0 z-10 pointer-events-none bg-[linear-gradient(to_right,rgba(9,9,11,1),transparent_20%,transparent_80%,rgba(9,9,11,1))]" />

      <div className="flex w-max">
        <motion.div
          className="flex gap-16 px-8"
          animate={{ x: "-50%" }}
          transition={{ duration: 60, repeat: Infinity, ease: "linear" }}
          whileHover={{ animationPlayState: "paused" }} // Note: Framer Motion handles pause differently, commonly via hover logic or useAnimation. 
        // For simple "pause on hover", we can use CSS class or event logic. 
        // Here, let's use a simpler wrapper hover approach if framer pause is complex.
        >
          {/* Duplicating twice for seamless loop */}
          {[...technologies, ...technologies].map((tech, i) => (
            <div key={`${tech.name}-${i}`} className="flex items-center gap-3 opacity-50 hover:opacity-100 transition-opacity duration-300 group/item cursor-default">
              <svg viewBox="0 0 24 24" className="w-8 h-8 fill-current text-white" aria-hidden="true">
                <path d={tech.path} />
              </svg>
              <span className="text-sm font-bold uppercase tracking-widest text-white">{tech.name}</span>
            </div>
          ))}
        </motion.div>
      </div>

      {/* CSS Override for Pause on Hover - Framer Motion x CSS */}
      <style jsx global>{`
           .group:hover .flex {
               /* Pausing Framer Motion animation via CSS is tricky. 
                  Alternative: Use marquee CSS animation instead of Framer Motion for easy hover-pause. */
           }
       `}</style>

      <div className="absolute inset-0 flex items-center pointer-events-none">
        {/* Re-implementing with pure CSS marquee for reliable "Pause on Hover" */}
        <div className="flex w-full overflow-hidden pointer-events-auto">
          <div className="flex animate-marquee gap-16 px-8 hover:[animation-play-state:paused]">
            {[...technologies, ...technologies, ...technologies].map((tech, i) => (
              <div key={`t1-${i}`} className="flex items-center gap-3 opacity-50 hover:opacity-100 transition-opacity duration-300 shrink-0">
                <svg viewBox="0 0 24 24" className="w-6 h-6 fill-current text-white">
                  <path d={tech.path} />
                </svg>
                <span className="text-sm font-bold uppercase tracking-widest text-white">{tech.name}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

    </section>
  );
}
